package com.example.riskplatform.controller;import com.example.riskplatform.common.ApiResponse;import com.example.riskplatform.dto.Requests.CompetitorRequest;import com.example.riskplatform.entity.Competitor;import com.example.riskplatform.service.CompetitorService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/competitors") @RequiredArgsConstructor public class CompetitorController{private final CompetitorService s;@GetMapping @PreAuthorize("hasAuthority('competitor:read')")public ApiResponse<List<Competitor>>list(@RequestParam(required=false)Long companyId){return ApiResponse.ok(s.list(companyId));}@PostMapping @PreAuthorize("hasAuthority('competitor:write')")public ApiResponse<Competitor>create(@Valid @RequestBody CompetitorRequest r){return ApiResponse.ok(s.create(r));}}